def is_bipartite(graph):
    n = len(graph)
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue
        color[start] = 0
        stack = [start]
        while stack:
            u = stack.pop()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    stack.append(v)
                elif color[v] == color[u]:
                    return False
    return True

print(is_bipartite([[1, 3], [0, 2], [1, 3], [0, 2]]))
print(is_bipartite([[1, 2], [0, 2], [0, 1]]))
print(is_bipartite([]))
